<?php $config = array("private_key_bits" => 2048, "private_key_type" => OPENSSL_KEYTYPE_RSA); $res = openssl_pkey_new($config); openssl_pkey_export($res, $privateKey); $publicKey = openssl_pkey_get_details($res)["key"]; file_put_contents("flow_private.pem", $privateKey); file_put_contents("flow_public.pem", $publicKey); echo "Success";
